@layer components {
  :where([data-control-family="pagination"][data-slot="root"]) {
    --cui-pagination-link-height: var(--control-h-sm);
    --cui-pagination-link-radius: var(--radius-control);
    --cui-pagination-link-background: transparent;
    --cui-pagination-link-hover-background: var(--hover-fill);
    --cui-pagination-link-active-background: var(--control-fill);
    --cui-pagination-link-active-border-color: var(--border);
    --cui-pagination-link-foreground: var(--foreground);
    --cui-pagination-link-shadow: 0 0 transparent;
    --cui-pagination-link-active-shadow: var(--shadow-sm);
    --cui-pagination-link-font-size: var(--text-body);
  }

  :where([data-control-family="pagination"][data-slot="content"]) {
    gap: calc(var(--spacing) * 1);
  }

  :where([data-control-family="pagination"][data-slot="link"]) {
    --_pagination-link-background: var(--cui-pagination-link-background);
    --_pagination-link-border-color: transparent;
    --_pagination-link-shadow: var(--cui-pagination-link-shadow);
    gap: calc(var(--spacing) * 1);
    block-size: var(--cui-pagination-link-height);
    min-inline-size: var(--cui-pagination-link-height);
    padding-inline: calc(var(--spacing) * 2.5);
    border-radius: var(--cui-pagination-link-radius);
    background: var(--_pagination-link-background);
    box-shadow:
      inset 0 0 0 var(--control-rim-width) var(--_pagination-link-border-color),
      var(--_pagination-link-shadow);
    color: var(--cui-pagination-link-foreground);
    font-size: var(--cui-pagination-link-font-size);
    font-variant-numeric: tabular-nums;
    cursor: pointer;
  }

  :where([data-control-family="pagination"][data-slot="link"][data-active="true"]) {
    --_pagination-link-background: var(--cui-pagination-link-active-background);
    --_pagination-link-border-color: var(--cui-pagination-link-active-border-color);
    --_pagination-link-shadow: var(--cui-pagination-link-active-shadow);
  }

  @media (hover: hover) {
    :where([data-control-family="pagination"][data-slot="link"]:hover:not([aria-disabled="true"])) {
      background: var(--cui-pagination-link-hover-background);
    }
  }

  :where([data-control-family="pagination"][data-slot="link"][aria-disabled="true"]) {
    opacity: var(--disabled-opacity);
    cursor: not-allowed;
  }

  @media (forced-colors: active) {
    :where([data-control-family="pagination"][data-slot="link"][data-active="true"]:not(:focus-visible)) {
      outline: var(--focus-ring-width) solid Highlight;
      outline-offset: calc(var(--focus-ring-width) * -1);
    }
  }

  :where([data-control-family="pagination"][data-slot="link"]:has(> svg:first-child)) {
    padding-inline-start: calc(var(--spacing) * 2);
  }

  :where([data-control-family="pagination"][data-slot="link"]:has(> svg:last-child)) {
    padding-inline-end: calc(var(--spacing) * 2);
  }

  :where([data-control-family="pagination"][data-slot="ellipsis"]) {
    block-size: var(--cui-pagination-link-height);
    min-inline-size: var(--cui-pagination-link-height);
    color: var(--muted-foreground);
  }

  :where([data-control-family="pagination"]:is([data-slot="link"], [data-slot="ellipsis"]) > svg) {
    flex-shrink: 0;
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
  }

  @media (pointer: coarse) {
    :where([data-control-family="pagination"][data-slot="link"]) {
      position: relative;
    }

    :where([data-control-family="pagination"][data-slot="link"])::after {
      content: "";
      position: absolute;
      inset-inline: 0;
      inset-block-start: 50%;
      translate: 0 -50%;
      block-size: max(100%, var(--touch-target));
    }
  }
}

@property --cui-pagination-link-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

